@spec tuning_spec  src=tests/specs/tuning_spec.lua  loc=439  cases=32
@exercises tuning (tuning)
@surface   tuning.derive, tuning.stepToText, tuning.scalaPitch, tuning.midiToStep, tuning.stepToMidi, tuning.parseScalaFile, tuning.parseScalaPitches, tuning.scalaToTemper, tuning.genEqual, tuning.edoDegrees, tuning.degreesToSpec, tuning.genHarmonics, tuning.genSubharmonics, tuning.parseChord, tuning.genChord, tuning.genCPS, tuning.genRank2, tuning.nextMosSize, tuning.mosInfo

# Intent
  Pins tuning.lua's pure display + derivation layer: the Option-B nameless
  step labels, the derived octaveStep / cellWidth fields, and the coordinate
  conversions between MIDI and step-octave. Realisation invariants (I1-I5)
  live in tm_tuning_spec; projection wiring in view_context_spec.

# Helpers
  @fn nameless(cents)  @ 9-11
  @fn rooted(root)  @ 14-20
      -- A 12EDO scale with the root fields the case is about; everything else default.

# Cases
  @case 'preset EDOs derive width 3 and a past-the-end octaveStep'  [pure]  @ 24-34
  @case 'named step renders name + octave'  [pure]  @ 38-43
  @case 'nameless step falls back to degree-octave with a dash'  [pure]  @ 47-55
  @case 'nameless scale past 9 steps widens the cell for 2-digit degrees'  [pure]  @ 59-66
  @case 'sub-octave period widens the octave field for 2-digit octaves'  [pure]  @ 70-79
  @case 'derive recomputes width when names are dropped'  [pure]  @ 83-91
  @case 'partially named scale: named steps keep their label, blanks fall back'  [pure]  @ 95-102
  @case 'scalaPitch parses ratios, cents, bare integers and n\\m steps'  [pure]  @ 106-120
  @case 'derive compiles pitches → cents and periodPitch → period'  [pure]  @ 124-132
  @case 'derive reduces an authored root to rootCents + octaveBase'  [pure]  @ 136-146
  @case 'a preset states no root and derives the default (0,0) = (1,-1)'  [pure]  @ 150-159
  @case 'the default root reduces the conversions to MIDI-relative arithmetic'  [pure]  @ 163-178
  @case 'a flattened root moves every pitch by its offset and renames nothing'  [pure]  @ 182-204
  @case 'an octave-shifted root renames every octave and moves no pitch'  [pure]  @ 208-224
  @case 'the conversions invert each other at every root'  [pure]  @ 228-241
  @case 'EDO presets carry n\\m source tokens that derive back to their cents'  [pure]  @ 245-252
  @case 'parseScalaFile strips comments, description and count; returns pitch tokens'  [pure]  @ 256-264
  @case 'parseScalaPitches keeps every non-comment, non-blank line'  [pure]  @ 268-273
  @case 'scalaToTemper prepends the unison, splits the period, flags periodAsStep'  [pure]  @ 277-288
  @case 'scalaToTemper sorts unordered pitches ascending; widest becomes the period'  [pure]  @ 292-301
  @case 'scalaToTemper rejects an unparseable token'  [pure]  @ 305-310
  @case 'genEqual: full EDO and a diatonic subset, base implicit, period last'  [pure]  @ 314-326
  @case 'edoDegrees: relative cumulates, absolute sorts; non-octave equave suffixes'  [pure]  @ 330-338
  @case 'degreesToSpec round-trips edoDegrees in both modes'  [pure]  @ 342-346
  @case 'genHarmonics / genSubharmonics: rooted on the low harmonic, top is period'  [pure]  @ 350-359
  @case 'genChord: otonal vs inverted, last member is the period'  [pure]  @ 363-375
  @case 'parseChord rejects fewer than two notes or non-integers'  [pure]  @ 379-383
  @case 'genCPS: hexany rooted on the smallest product, 1/1 first, ascending'  [pure]  @ 387-393
  @case 'genRank2: pure-fifth size 7 / up 5 is Pythagorean major, 1/1 first'  [pure]  @ 397-403
  @case 'genRank2: size 4 / up 2 matches the Scale Workshop worked example'  [pure]  @ 407-412
  @case 'genRank2: irrational (EDO-step) generator emits cents tokens'  [pure]  @ 416-421
  @case 'nextMosSize / mosInfo: pure-fifth ladder 2->3->5->7->12; 7 is 5L 2s'  [pure]  @ 425-437

